# Compute connected placements for a 4x4 movable block; any non-3 cell is traversable.
H=W=4
anchors4={(r,c) for r in range(20-H+1) for c in range(20-W+1) if all(g2[i][j]!=3 for i in range(r,r+H) for j in range(c,c+W))}
start4=(11,1)
q=collections.deque([start4]); prev4={start4:None}
while q:
 a=q.popleft()
 for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
  b=(a[0]+dr,a[1]+dc)
  if b in anchors4 and b not in prev4: prev4[b]=a;q.append(b)
deg={a:sum((a[0]+dr,a[1]+dc) in prev4 for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]) for a in prev4}
print('all anchors',len(anchors4),'reachable',len(prev4))
print('reachable sorted',sorted(prev4))
print('degrees',sorted((a,d) for a,d in deg.items()))
print('endpoints', [a for a,d in deg.items() if d<=1])
print('2-block anchor',(14,16),'exists?',(14,16) in prev4)
